const { question, context } = $json.body || {};
if (!question || !question.trim()) {
  return [{ json: { ok: false, error: 'question is required' } }];
}
return [{ json: {
  question: question.trim(),
  context: context || '',
  timestamp: new Date().toISOString()
}}];

const items = $input.all();
const pro = items.find(i => i.json.role === 'pro') || items[0];
const con = items.find(i => i.json.role !== 'pro') || items[1];

const proArg = pro.json.output || pro.json.text || '';
const conArg = con.json.output || con.json.text || '';

return [{ json: {
  question: $json.question,
  proArgument: proArg,
  proAgent: pro.json.agent || 'Agent A',
  conArgument: conArg,
  conAgent: con.json.agent || 'Agent B',
  context: $json.context
}}];

const verdict = $json.output || $json.text || '';
return [{ json: {
  ok: true,
  question: $json.question,
  verdict,
  timestamp: new Date().toISOString()
}}];
